// PyLearn service worker: precaches the whole app (including Pyodide) so it
// works offline after the first visit. Generated by build.py - do not edit.
const VERSION = "72999013505c";
const CACHE = "pylearn-" + VERSION;
const ASSETS = [
 "./",
 "app.js",
 "data/lessons.json",
 "data/runner.py",
 "data/runtime.json",
 "icons/apple-touch-icon.png",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/icon-maskable-512.png",
 "icons/icon.svg",
 "index.html",
 "manifest.json",
 "pyodide/pyodide-lock.json",
 "pyodide/pyodide.asm.mjs",
 "pyodide/pyodide.asm.wasm",
 "pyodide/pyodide.js",
 "pyodide/pyodide.mjs",
 "pyodide/python_stdlib.zip",
 "style.css",
 "worker.js"
];

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(ASSETS.map((u) => new Request(u, { cache: "reload" })));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys())
      if (key.startsWith("pylearn-") && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET" || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    let hit = await cache.match(req, { ignoreSearch: true });
    if (!hit && req.mode === "navigate") hit = await cache.match("./index.html");
    if (hit) return hit;
    return fetch(req);
  })());
});
